package com.example.starter.observation.geofence;

/**
 * 观测证据的围栏匹配结果与当前状态。
 * match_result 落库后不可变；status 仅允许经人工裁决由 GEOFENCE_REJECTED 改为 ACCEPTED。
 */
public enum ObservationStatus {

    /**
     * 接受：落在生效围栏内，或采集时刻站点无生效围栏；参与自动合并。
     */
    ACCEPTED,

    /**
     * 围栏拒绝：采集时刻落在生效围栏外；不参与自动合并，保留原始证据。
     */
    GEOFENCE_REJECTED
}

package com.example.starter.observation.geofence;

import com.fasterxml.jackson.annotation.JsonInclude;

/**
 * 422 校验失败明细：数量、时长、坐标等给出实际值、要求值，可计算时给出差额。
 *
 * @param field      出错字段（批量条目带下标，如 items[0].latitude）
 * @param actual     实际值原文
 * @param required   要求值或合法范围描述
 * @param difference 实际值与最近越界边界的差额；不适用时为 null
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record ValidationDetail(
        String field,
        String actual,
        String required,
        String difference) {
}

package com.example.starter.observation.geofence;

import java.util.List;

/**
 * 地理围栏语义校验异常：经纬度范围、围栏边界、生效区间、批量数量等非法时抛出，
 * 由全局处理器转为 422 响应；抛出前不写库，整批回滚且 requestId 不占键。
 */
