package com.example.starter.observation.geofence;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.util.Optional;

/**
 * 地理围栏模块幂等去重持久化：geofence_request_log 仅记录成功结果，
 * 与业务变更同事务原子提交；失败回滚不占键。所有 SQL 使用参数化查询。
 */
@Repository
public class GeofenceRequestLogRepository {

    private static final RowMapper<GeofenceRequestLogEntry> ENTRY_MAPPER = (rs, rowNum) -> new GeofenceRequestLogEntry(
            rs.getString("request_id"),
            rs.getString("fingerprint"),
            rs.getString("operation"),
            (Integer) rs.getObject("response_status"),
            rs.getString("response_body"));

    private final JdbcTemplate jdbcTemplate;

    public GeofenceRequestLogRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    /**
     * 按请求标识查询去重记录；不存在时返回空。
     */
    public Optional<GeofenceRequestLogEntry> find(String requestId) {
        return jdbcTemplate.query(
                        "SELECT request_id, fingerprint, operation, response_status, response_body "
                                + "FROM geofence_request_log WHERE request_id = ?",
                        ENTRY_MAPPER, requestId)
                .stream().findFirst();
    }

    /**
     * 在写事务内先占位插入去重记录（响应暂为空），主键冲突时由数据库串行化并发同键请求。
     * 业务失败时随事务回滚，不占用该键。
     */
    public void insertPlaceholder(String requestId, String fingerprint, String operation) {
        jdbcTemplate.update(
                "INSERT INTO geofence_request_log (request_id, fingerprint, operation, response_status, response_body, created_at) "
                        + "VALUES (?, ?, ?, NULL, NULL, CURRENT_TIMESTAMP)",
                requestId, fingerprint, operation);
    }

    /**
     * 业务成功后回填响应，与业务变更在同一事务内提交。
     */
    public void complete(String requestId, int responseStatus, String responseBody) {
        jdbcTemplate.update(
                "UPDATE geofence_request_log SET response_status = ?, response_body = ? WHERE request_id = ?",
                responseStatus, responseBody, requestId);
    }
}

package com.example.starter.observation.geofence;

import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.sql.Timestamp;
import java.time.Instant;
import java.util.List;
import java.util.Optional;

/**
 * 站点地理围栏持久化：site_geofence 保存全部不可变版本；geofence_site 提供站点级行锁，
 * 串行化同站点并发围栏写入，保证“同一站点任一时刻至多一个生效版本”的不变量。
 * 所有 SQL 使用参数化查询。
 */
@Repository
public class GeofenceRepository {

    private static final String VERSION_COLUMNS =
            "fence_id, fence_version, site_id, min_latitude, max_latitude, min_longitude, max_longitude, "
                    + "effective_from_utc, effective_to_utc, operator, request_id";

    private static final RowMapper<FenceVersionRecord> VERSION_MAPPER = (rs, rowNum) -> new FenceVersionRecord(
            rs.getString("fence_id"),
            rs.getInt("fence_version"),
            rs.getString("site_id"),
            rs.getBigDecimal("min_latitude"),
            rs.getBigDecimal("max_latitude"),
            rs.getBigDecimal("min_longitude"),
            rs.getBigDecimal("max_longitude"),
            rs.getTimestamp("effective_from_utc").toInstant(),
            rs.getTimestamp("effective_to_utc").toInstant(),
            rs.getString("operator"),
            rs.getString("request_id"));

    private final JdbcTemplate jdbcTemplate;

    public GeofenceRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    /**
     * 登记站点并加行锁（SELECT ... FOR UPDATE），串行化同站点围栏写事务。
     * 站点行不存在时先插入；并发插入由主键串行化，后到者读取已提交行。
     */
    public void lockSite(String siteId) {
        try {
            jdbcTemplate.update("INSERT INTO geofence_site (site_id, created_at) VALUES (?, CURRENT_TIMESTAMP)",
                    siteId);
        } catch (DuplicateKeyException e) {
            // 站点已登记（含并发登记）：忽略，统一走下面的行锁
        }
        jdbcTemplate.query("SELECT site_id FROM geofence_site WHERE site_id = ? FOR UPDATE",
                (rs, rowNum) -> rs.getString("site_id"), siteId);
    }

    /**
     * 判断围栏标识是否已存在（任意版本）。
     */
    public boolean existsFence(String fenceId) {
        Integer count = jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM site_geofence WHERE fence_id = ?", Integer.class, fenceId);
        return count != null && count > 0;
    }

    /**
     * 查询围栏的最新版本；不存在时返回空。
     */
    public Optional<FenceVersionRecord> findLatestVersion(String fenceId) {
        return jdbcTemplate.query(
                        "SELECT " + VERSION_COLUMNS + " FROM site_geofence WHERE fence_id = ? "
                                + "ORDER BY fence_version DESC LIMIT 1",
                        VERSION_MAPPER, fenceId)
                .stream().findFirst();
    }

    /**
     * 查询围栏的全部版本，按版本号升序。
     */
    public List<FenceVersionRecord> findVersions(String fenceId) {
        return jdbcTemplate.query(
                "SELECT " + VERSION_COLUMNS + " FROM site_geofence WHERE fence_id = ? ORDER BY fence_version ASC",
                VERSION_MAPPER, fenceId);
    }

    /**
     * 查询站点全部围栏版本，按生效起始时刻、围栏标识、版本号升序（排序稳定）。
     */
    public List<FenceVersionRecord> findBySite(String siteId) {
        return jdbcTemplate.query(
                "SELECT " + VERSION_COLUMNS + " FROM site_geofence WHERE site_id = ? "
                        + "ORDER BY effective_from_utc ASC, fence_id ASC, fence_version ASC",
                VERSION_MAPPER, siteId);
    }

    /**
     * 查询与新区间 [from, to) 重叠的同站点围栏版本（含其他围栏与历史版本）。
     */
    public List<FenceVersionRecord> findOverlapping(String siteId, Instant fromUtc, Instant toUtc) {
        return jdbcTemplate.query(
                "SELECT " + VERSION_COLUMNS + " FROM site_geofence "
                        + "WHERE site_id = ? AND effective_from_utc < ? AND effective_to_utc > ? "
                        + "ORDER BY fence_id ASC, fence_version ASC",
                VERSION_MAPPER, siteId, Timestamp.from(toUtc), Timestamp.from(fromUtc));
    }

    /**
     * 按采集时刻匹配站点生效围栏版本；同站点任一时刻至多一个生效版本（由重叠校验保证）。
     */
    public Optional<FenceVersionRecord> findEffective(String siteId, Instant observedAtUtc) {
        return jdbcTemplate.query(
                        "SELECT " + VERSION_COLUMNS + " FROM site_geofence "
                                + "WHERE site_id = ? AND effective_from_utc <= ? AND effective_to_utc > ? "
                                + "ORDER BY fence_id ASC, fence_version ASC LIMIT 1",
                        VERSION_MAPPER, siteId, Timestamp.from(observedAtUtc), Timestamp.from(observedAtUtc))
                .stream().findFirst();
    }

    /**
     * 追加一个不可变围栏版本。
     */
    public void insertVersion(FenceVersionRecord record) {
        jdbcTemplate.update(
                "INSERT INTO site_geofence (fence_id, fence_version, site_id, min_latitude, max_latitude, "
                        + "min_longitude, max_longitude, effective_from_utc, effective_to_utc, operator, request_id, "
                        + "created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)",
                record.fenceId(), record.fenceVersion(), record.siteId(),
                record.minLatitude(), record.maxLatitude(), record.minLongitude(), record.maxLongitude(),
                Timestamp.from(record.effectiveFromUtc()), Timestamp.from(record.effectiveToUtc()),
                record.operator(), record.requestId());
    }
}

package com.example.starter.observation.geofence;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.sql.Timestamp;
import java.util.List;
import java.util.Optional;

/**
 * 观测证据持久化：geofence_observation 落库后不可变，仅 status 可经人工裁决更新。
 * 所有 SQL 使用参数化查询。
 */
@Repository
public class GeofenceObservationRepository {

    private static final String EVIDENCE_COLUMNS =
            "observation_id, request_id, batch_seq, site_id, latitude, longitude, observed_at_utc, payload, "
                    + "match_result, status, matched_fence_id, matched_fence_version, operator, submitted_at_utc";

    private static final RowMapper<ObservationEvidenceRecord> EVIDENCE_MAPPER = (rs, rowNum) -> new ObservationEvidenceRecord(
            rs.getString("observation_id"),
            rs.getString("request_id"),
            rs.getInt("batch_seq"),
            rs.getString("site_id"),
            rs.getBigDecimal("latitude"),
            rs.getBigDecimal("longitude"),
            rs.getTimestamp("observed_at_utc").toInstant(),
            rs.getString("payload"),
            rs.getString("match_result"),
            rs.getString("status"),
            rs.getString("matched_fence_id"),
            (Integer) rs.getObject("matched_fence_version"),
            rs.getString("operator"),
            rs.getTimestamp("submitted_at_utc").toInstant());

    private final JdbcTemplate jdbcTemplate;

    public GeofenceObservationRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    /**
     * 按观测标识查询证据（不加锁），用于查询接口。
     */
    public Optional<ObservationEvidenceRecord> find(String observationId) {
        return jdbcTemplate.query(
                        "SELECT " + EVIDENCE_COLUMNS + " FROM geofence_observation WHERE observation_id = ?",
                        EVIDENCE_MAPPER, observationId)
                .stream().findFirst();
    }

    /**
     * 按观测标识查询证据并加行锁（SELECT ... FOR UPDATE），用于裁决事务内串行化。
     */
    public Optional<ObservationEvidenceRecord> findForUpdate(String observationId) {
        return jdbcTemplate.query(
                        "SELECT " + EVIDENCE_COLUMNS + " FROM geofence_observation WHERE observation_id = ? FOR UPDATE",
                        EVIDENCE_MAPPER, observationId)
                .stream().findFirst();
    }

    /**
     * 批量查询已存在的观测标识，用于批量提交前的冲突预检。
     */
    public List<String> findExistingIds(List<String> observationIds) {
        String placeholders = String.join(", ", observationIds.stream().map(id -> "?").toList());
        return jdbcTemplate.query(
                "SELECT observation_id FROM geofence_observation WHERE observation_id IN (" + placeholders + ") "
                        + "ORDER BY observation_id ASC",
                (rs, rowNum) -> rs.getString("observation_id"), observationIds.toArray());
    }

    /**
     * 按站点查询观测证据，可按状态过滤；按提交时刻、观测标识升序（排序稳定）。
     */
    public List<ObservationEvidenceRecord> findBySite(String siteId, String status) {
        if (status == null) {
            return jdbcTemplate.query(
                    "SELECT " + EVIDENCE_COLUMNS + " FROM geofence_observation WHERE site_id = ? "
                            + "ORDER BY submitted_at_utc ASC, observation_id ASC",
                    EVIDENCE_MAPPER, siteId);
        }
        return jdbcTemplate.query(
                "SELECT " + EVIDENCE_COLUMNS + " FROM geofence_observation WHERE site_id = ? AND status = ? "
                        + "ORDER BY submitted_at_utc ASC, observation_id ASC",
                EVIDENCE_MAPPER, siteId, status);
    }

    /**
     * 插入一条观测证据；observation_id 主键冲突时抛出重复键异常。
     */
    public void insert(ObservationEvidenceRecord record) {
        jdbcTemplate.update(
                "INSERT INTO geofence_observation (observation_id, request_id, batch_seq, site_id, latitude, longitude, "
                        + "observed_at_utc, payload, match_result, status, matched_fence_id, matched_fence_version, "
                        + "operator, submitted_at_utc, created_at) "
                        + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)",
                record.observationId(), record.requestId(), record.batchSeq(), record.siteId(),
                record.latitude(), record.longitude(), Timestamp.from(record.observedAtUtc()), record.payload(),
                record.matchResult(), record.status(), record.matchedFenceId(), record.matchedFenceVersion(),
                record.operator(), Timestamp.from(record.submittedAtUtc()));
    }

    /**
     * 人工裁决后更新当前状态；其余字段不可变。
     */
    public void updateStatus(String observationId, String status) {
        jdbcTemplate.update(
                "UPDATE geofence_observation SET status = ? WHERE observation_id = ?",
                status, observationId);
    }
}

package com.example.starter.observation.geofence;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.sql.Timestamp;
import java.util.List;
import java.util.Optional;

/**
 * 人工裁决记录持久化：geofence_adjudication 记录成功裁决的完整上下文，不可变、永不更新。
 * 所有 SQL 使用参数化查询。
 */
@Repository
public class GeofenceAdjudicationRepository {

    private static final RowMapper<AdjudicationRecord> RECORD_MAPPER = (rs, rowNum) -> new AdjudicationRecord(
            rs.getString("adjudication_id"),
            rs.getString("observation_id"),
            rs.getString("request_id"),
            rs.getString("decision"),
            rs.getString("reason"),
            rs.getString("operator"),
            rs.getTimestamp("adjudicated_at_utc").toInstant());

    private final JdbcTemplate jdbcTemplate;

    public GeofenceAdjudicationRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    /**
     * 插入一条不可变裁决记录；adjudication_id 主键或 observation_id 唯一键冲突时抛出重复键异常。
     */
    public void insert(AdjudicationRecord record) {
        jdbcTemplate.update(
                "INSERT INTO geofence_adjudication (adjudication_id, observation_id, request_id, decision, reason, "
                        + "operator, adjudicated_at_utc, created_at) "
                        + "VALUES (?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)",
                record.adjudicationId(), record.observationId(), record.requestId(), record.decision(),
                record.reason(), record.operator(), Timestamp.from(record.adjudicatedAtUtc()));
    }

    /**
     * 按全局唯一 adjudicationId 查询裁决记录；不存在时返回空。
     */
    public Optional<AdjudicationRecord> findByAdjudicationId(String adjudicationId) {
        return jdbcTemplate.query(
                        "SELECT adjudication_id, observation_id, request_id, decision, reason, operator, adjudicated_at_utc "
