        adjudicate("obs-rej", "req-a12", "adj-2", "op-review", "理由")
                .andExpect(status().isConflict());
        Integer count = jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM geofence_adjudication", Integer.class);
